Box {
    MonarchButton(
        text = {{trigger}},
        onClick = { expanded = true },
        trailingIcon = { MonarchIcon(SampleIcons.More, contentDescription = null) },
    )
    MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
        MonarchMenuLabel(text = {{label}})
        MonarchMenuItem(text = {{items.0.label}}, onClick = { expanded = false }, shortcut = {{items.0.shortcut}})
        MonarchMenuItem(text = {{items.1.label}}, onClick = { expanded = false })
        MonarchMenuItem(text = {{watching.label}}, onClick = { expanded = false }, selected = {{watching.checked}})
        MonarchMenuDivider()
        MonarchMenuItem(text = {{delete}}, onClick = { expanded = false }, destructive = true)
    }
}

