Box {
    MonarchButton(
        text = "Actions",
        onClick = { expanded = true },
        trailingIcon = { MonarchIcon(SampleIcons.More, contentDescription = null) },
    )
    MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
        MonarchMenuLabel(text = "Ticket")
        MonarchMenuItem(text = "Rename", onClick = { expanded = false }, shortcut = "R")
        MonarchMenuItem(text = "Assign to me", onClick = { expanded = false })
        MonarchMenuItem(text = "Watching", onClick = { expanded = false }, selected = true)
        MonarchMenuDivider()
        MonarchMenuItem(text = "Delete", onClick = { expanded = false }, destructive = true)
    }
}

Box {
    MonarchButton(text = "Actions", onClick = { expanded = true })
    MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
        MonarchMenuItem(text = "Edit", onClick = { expanded = false })
        MonarchMenuItem(text = "Duplicate", onClick = { expanded = false })
        MonarchMenuItem(text = "Move", onClick = {}, enabled = false)
        MonarchMenuDivider()
        MonarchMenuItem(text = "Delete", onClick = { expanded = false }, destructive = true)
    }
}

Box {
    MonarchButton(text = "View", onClick = { expanded = true }, variant = MonarchButtonVariant.Ghost)
    MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
        MonarchMenuItem(
            onClick = { showArchived = !showArchived },
            modifier = Modifier.semantics { stateDescription = if (showArchived) "On" else "Off" },
            trailingContent = { MonarchCheckbox(checked = showArchived, onCheckedChange = null) },
        ) { Text("Show archived") }
        MonarchMenuItem(
            text = "Search",
            onClick = { expanded = false },
            leadingIcon = { MonarchIcon(SampleIcons.Search, contentDescription = null) },
        )
    }
}
